
.recruit-overlay {
  position: fixed;
  inset: 0;
  z-index: 50;
  display: grid;
  place-items: center;
  padding: 16px;
  background: rgba(4, 5, 8, 0.72);
  backdrop-filter: blur(8px);
  animation: overlay-in 0.25s ease;
}
@keyframes overlay-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
.recruit-panel {
  width: min(640px, 100%);
  max-height: 84vh;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--line-strong);
  border-radius: 18px;
  background: linear-gradient(160deg, rgba(24, 29, 42, 0.95), rgba(13, 16, 24, 0.98));
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.55);
  overflow: hidden;
  animation: panel-in 0.3s cubic-bezier(0.34, 1.4, 0.44, 1);
}
@keyframes panel-in {
  from {
    opacity: 0;
    transform: translateY(16px) scale(0.97);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.recruit-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px;
  border-bottom: 1px solid var(--line);
}
.recruit-title {
  font-family: var(--font-serif);
  font-size: 16px;
  letter-spacing: 0.08em;
  color: var(--bone);
}
.load-close {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 8px;
  color: var(--ash-dim);
  cursor: pointer;
  transition: all 0.2s ease;
}
.load-close :deep(svg) {
  width: 15px;
  height: 15px;
}
.load-close:hover {
  color: var(--bone);
  border-color: var(--line-bright);
  background: rgba(230, 226, 216, 0.06);
}

.recruit-tabs {
  display: flex;
  gap: 6px;
  padding: 12px 16px 0;
}
.recruit-tab {
  flex: 1;
  padding: 8px 6px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: rgba(230, 226, 216, 0.02);
  color: var(--ash-dim);
  font-family: var(--font-serif);
  font-size: 13px;
  letter-spacing: 0.05em;
  cursor: pointer;
  transition: all 0.2s ease;
}
.recruit-tab:hover {
  color: var(--bone);
  border-color: var(--line-bright);
}
.recruit-tab.active {
  color: var(--gold-soft);
  border-color: rgba(212, 168, 96, 0.45);
  background: linear-gradient(90deg, rgba(212, 168, 96, 0.14), rgba(212, 168, 96, 0.03));
}

.recruit-body {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 14px 16px 16px;
  overflow-y: auto;
}
.recruit-refresh {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 9px 14px;
  border: 1px solid var(--line-strong);
  border-radius: 11px;
  background: rgba(230, 226, 216, 0.03);
  color: var(--ash);
  font-family: var(--font-serif);
  font-size: 13px;
  letter-spacing: 0.06em;
  cursor: pointer;
  transition: all 0.2s ease;
}
.recruit-refresh:hover:not(:disabled) {
  color: var(--bone);
  border-color: var(--line-bright);
  background: rgba(230, 226, 216, 0.06);
}
.recruit-refresh:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.refresh-icon {
  width: 15px;
  height: 15px;
  display: grid;
  place-items: center;
  color: var(--gold);
}
.refresh-icon :deep(svg) {
  width: 14px;
  height: 14px;
}

.candidate {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 13px 14px;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: rgba(230, 226, 216, 0.02);
}
.candidate-head {
  display: flex;
  align-items: center;
  gap: 10px;
}
.candidate-name {
  font-family: var(--font-serif);
  font-size: 16px;
  font-weight: 600;
  color: var(--bone);
  letter-spacing: 0.04em;
}
.candidate-meta {
  font-size: 12px;
  color: var(--ash-dim);
}
.candidate-badge {
  margin-left: auto;
  font-family: var(--font-display);
  font-size: 11px;
  color: var(--gold-soft);
  border: 1px solid rgba(212, 168, 96, 0.4);
  border-radius: 999px;
  padding: 1px 9px;
  background: rgba(212, 168, 96, 0.08);
}
.candidate-line {
  font-size: 13px;
  line-height: 1.6;
  color: var(--ash);
}
.candidate-line i {
  font-style: normal;
  font-family: var(--font-serif);
  color: var(--ash-faint);
  letter-spacing: 0.1em;
  margin-right: 8px;
}
.candidate-yinxia {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 9px 11px;
  border: 1px solid rgba(156, 120, 192, 0.25);
  border-radius: 9px;
  background: rgba(156, 120, 192, 0.06);
}
.yinxia-title {
  font-family: var(--font-serif);
  font-size: 11px;
  letter-spacing: 0.2em;
  color: var(--violet);
}
.candidate-recruit {
  align-self: flex-end;
  padding: 6px 18px;
  border: 1px solid rgba(212, 168, 96, 0.45);
  border-radius: 9px;
  background: linear-gradient(135deg, var(--gold), #b98a43);
  color: #1a1208;
  font-family: var(--font-serif);
  font-size: 13px;
  letter-spacing: 0.06em;
  cursor: pointer;
  transition: all 0.2s ease;
}
.candidate-recruit:hover:not(:disabled) {
  filter: brightness(1.06);
  box-shadow: 0 4px 14px rgba(212, 168, 96, 0.35);
}
.candidate-recruit:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}
.candidate-empty {
  padding: 26px;
  text-align: center;
  color: var(--ash-faint);
  font-family: var(--font-serif);
  font-size: 13px;
}
