
.overview {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 14px 12px;
  min-height: 0;
}
.block {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.mini-list {
  display: flex;
  flex-direction: column;
  gap: 7px;
}
.mini-card {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 11px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: rgba(230, 226, 216, 0.02);
  color: var(--bone);
  text-align: left;
  cursor: pointer;
  transition: all 0.2s ease;
}
.mini-card:hover {
  border-color: rgba(212, 168, 96, 0.45);
  background: rgba(212, 168, 96, 0.06);
  transform: translateX(2px);
}
.mini-name {
  font-family: var(--font-serif);
  font-size: 13.5px;
  color: var(--bone);
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.mini-live {
  font-size: 11px;
  color: var(--ash-dim);
  white-space: nowrap;
}
.mini-live b {
  font-family: var(--font-display);
  color: var(--life);
}
