
.maintext-panel {
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-height: 0;
}

.mt-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
.mt-info {
  display: flex;
  align-items: center;
  gap: 10px;
  flex: 1;
  min-width: 0;
  flex-wrap: wrap;
}
.mt-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--gold);
  box-shadow: 0 0 8px var(--gold);
  flex: none;
}
.mt-location {
  font-family: var(--font-serif);
  font-size: 15px;
  font-weight: 600;
  letter-spacing: 0.05em;
  color: var(--bone);
}
.mt-time {
  font-family: var(--font-display);
  font-size: 11px;
  letter-spacing: 0.12em;
  color: var(--ash-dim);
}
.mt-fog {
  font-family: var(--font-display);
  font-size: 11px;
  letter-spacing: 0.1em;
  color: var(--ice);
  padding: 2px 9px;
  border: 1px solid rgba(143, 179, 201, 0.3);
  border-radius: 999px;
  background: rgba(143, 179, 201, 0.06);
}

.toolbar {
  display: flex;
  gap: 6px;
  flex: none;
}
.tool-btn {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: rgba(230, 226, 216, 0.02);
  color: var(--ash-dim);
  cursor: pointer;
  transition: all 0.2s ease;
}
.tool-btn :deep(svg) {
  width: 16px;
  height: 16px;
}
.tool-btn:hover {
  color: var(--bone);
  border-color: var(--line-bright);
  background: rgba(230, 226, 216, 0.06);
}
.tool-btn.active {
  color: var(--gold-soft);
  border-color: rgba(212, 168, 96, 0.45);
  background: rgba(212, 168, 96, 0.1);
}
.tool-btn:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.mt-body {
  padding: 16px 18px;
  min-height: 120px;
  max-height: 320px;
  overflow-y: auto;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: linear-gradient(160deg, rgba(230, 226, 216, 0.03), rgba(18, 22, 32, 0.4));
  font-family: var(--font-serif);
  font-size: 15px;
  line-height: 1.95;
  letter-spacing: 0.02em;
  color: var(--bone);
  white-space: pre-wrap;
  word-break: break-word;
}
.mt-body.longpressable {
  cursor: pointer;
  user-select: none;
}
.mt-body.is-empty {
  color: var(--ash-faint);
  font-family: var(--font-sans);
  font-size: 13px;
  display: grid;
  place-items: center;
  text-align: center;
  cursor: default;
}
/* 选项展开时收缩正文框，给选项和输入框让出空间 */
.maintext-panel.opts-open .mt-body {
  min-height: 80px;
  max-height: 150px;
}

.generating {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 18px;
  border: 1px dashed var(--line-strong);
  border-radius: 14px;
  color: var(--ash-dim);
  font-family: var(--font-serif);
  font-size: 13px;
  letter-spacing: 0.08em;
}
.gen-ring {
  width: 14px;
  height: 14px;
  flex: none;
  border: 2px solid rgba(212, 168, 96, 0.25);
  border-top-color: var(--gold);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
}
@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}
.generating.streaming {
  display: block;
  padding: 16px 18px;
  border-style: solid;
  border-color: var(--line);
  background: linear-gradient(160deg, rgba(230, 226, 216, 0.03), rgba(18, 22, 32, 0.4));
}
.streaming-text {
  font-family: var(--font-serif);
  font-size: 15px;
  line-height: 1.95;
  letter-spacing: 0.02em;
  color: var(--bone);
  white-space: pre-wrap;
  word-break: break-word;
  min-height: 120px;
  max-height: 320px;
  overflow-y: auto;
}
.typing-cursor {
  display: inline-block;
  width: 2px;
  height: 1em;
  margin-left: 2px;
  vertical-align: -0.12em;
  background: var(--gold);
  animation: blink 0.9s steps(1) infinite;
}
@keyframes blink {
  50% {
    opacity: 0;
  }
}

.options-wrap {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.options-toggle {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: rgba(230, 226, 216, 0.02);
  color: var(--ash);
  cursor: pointer;
  transition: all 0.22s ease;
}
.options-toggle:hover {
  color: var(--bone);
  border-color: var(--line-bright);
  background: rgba(230, 226, 216, 0.05);
}
.toggle-icon {
  width: 16px;
  height: 16px;
  display: grid;
  place-items: center;
  color: var(--gold);
  transition: transform 0.25s ease;
}
.toggle-icon :deep(svg) {
  width: 15px;
  height: 15px;
}
.toggle-icon.open {
  transform: rotate(180deg);
}
.toggle-label {
  font-family: var(--font-serif);
  font-size: 13px;
  letter-spacing: 0.08em;
  flex: 1;
  text-align: left;
}
.toggle-badge {
  font-family: var(--font-display);
  font-size: 11px;
  color: var(--gold-soft);
  border: 1px solid rgba(212, 168, 96, 0.4);
  border-radius: 999px;
  padding: 1px 9px;
  background: rgba(212, 168, 96, 0.08);
}

.collapse-enter-active,
.collapse-leave-active {
  transition: opacity 0.25s ease, transform 0.25s ease;
}
.collapse-enter-from,
.collapse-leave-to {
  opacity: 0;
  transform: translateY(-6px);
}

.options {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.option {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 11px 14px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: rgba(230, 226, 216, 0.02);
  color: var(--ash);
  text-align: left;
  cursor: pointer;
  animation: option-in 0.45s cubic-bezier(0.22, 0.9, 0.34, 1) backwards;
  animation-delay: var(--d, 0ms);
  transition: border-color 0.22s ease, background 0.22s ease, transform 0.22s ease, box-shadow 0.22s ease, color 0.22s ease;
}
@keyframes option-in {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.option:hover {
  color: var(--bone);
  border-color: rgba(212, 168, 96, 0.5);
  background: linear-gradient(90deg, rgba(212, 168, 96, 0.12), rgba(212, 168, 96, 0.02));
  transform: translateX(3px);
  box-shadow: 0 6px 22px rgba(0, 0, 0, 0.35);
}
.option:active {
  transform: translateX(3px) scale(0.99);
}
.option-badge {
  width: 26px;
  height: 26px;
  flex: none;
  display: grid;
  place-items: center;
  border: 1px solid rgba(212, 168, 96, 0.4);
  border-radius: 8px;
  font-family: var(--font-display);
  font-size: 12px;
  font-weight: 600;
  color: var(--gold-soft);
  background: rgba(212, 168, 96, 0.06);
  transition: all 0.22s ease;
}
.option:hover .option-badge {
  background: var(--gold);
  color: #1a1208;
  box-shadow: 0 0 14px rgba(212, 168, 96, 0.5);
}
.option-text {
  flex: 1;
  min-width: 0;
  font-family: var(--font-serif);
  font-size: 13.5px;
  letter-spacing: 0.03em;
  line-height: 1.5;
}
.option-arrow {
  width: 16px;
  height: 16px;
  flex: none;
  display: grid;
  place-items: center;
  color: var(--ash-faint);
  transition: transform 0.22s ease, color 0.22s ease;
}
.option-arrow :deep(svg) {
  width: 15px;
  height: 15px;
}
.option:hover .option-arrow {
  color: var(--gold);
  transform: translateX(3px);
}

.composer {
  display: flex;
  gap: 8px;
  align-items: center;
}
.composer-input {
  flex: 1;
  min-width: 0;
  padding: 10px 14px;
  border: 1px solid var(--line-strong);
  border-radius: 12px;
  background: rgba(11, 14, 20, 0.6);
  color: var(--bone);
  font-family: var(--font-sans);
  font-size: 13.5px;
  outline: none;
  transition: border-color 0.22s ease, box-shadow 0.22s ease;
}
.composer-input::placeholder {
  color: var(--ash-faint);
}
.composer-input:focus {
  border-color: rgba(212, 168, 96, 0.5);
  box-shadow: 0 0 0 3px rgba(212, 168, 96, 0.12);
}
.composer-input:disabled {
  opacity: 0.5;
}
.composer-send {
  width: 42px;
  height: 42px;
  flex: none;
  display: grid;
  place-items: center;
  border-radius: 12px;
  background: linear-gradient(135deg, var(--gold), #b98a43);
  color: #1a1208;
  box-shadow: 0 4px 16px rgba(212, 168, 96, 0.3);
  cursor: pointer;
  transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease, opacity 0.2s ease;
}
.composer-send :deep(svg) {
  width: 18px;
  height: 18px;
}
.composer-send:hover:not(:disabled) {
  transform: translateY(-1px);
  filter: brightness(1.06);
  box-shadow: 0 6px 22px rgba(212, 168, 96, 0.42);
}
.composer-send:active:not(:disabled) {
  transform: scale(0.95);
}
.composer-send:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  box-shadow: none;
}

.reading-mode {
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-height: 0;
}
.reading-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  padding-bottom: 6px;
  border-bottom: 1px solid var(--line);
}
.reading-title {
  font-family: var(--font-serif);
  font-size: 13px;
  letter-spacing: 0.16em;
  color: var(--bone);
}
.reading-count {
  font-family: var(--font-display);
  font-size: 11px;
  color: var(--ash-faint);
  letter-spacing: 0.1em;
}
.reading-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
  max-height: 56vh;
  overflow-y: auto;
  padding-right: 2px;
}
.reading-item {
  border: 1px solid var(--line);
  border-radius: 12px;
  background: rgba(230, 226, 216, 0.02);
  padding: 11px 14px;
}
.reading-floor {
  font-family: var(--font-display);
  font-size: 10px;
  letter-spacing: 0.16em;
  color: var(--gold);
  margin-bottom: 5px;
}
.reading-text {
  font-family: var(--font-serif);
  font-size: 13.5px;
  line-height: 1.85;
  color: var(--ash);
  white-space: pre-wrap;
  word-break: break-word;
}
.reading-empty {
  padding: 24px;
  text-align: center;
  color: var(--ash-faint);
  font-family: var(--font-serif);
  font-size: 13px;
}

.load-overlay,
.edit-overlay {
  position: fixed;
  inset: 0;
  z-index: 50;
  display: grid;
  place-items: center;
  padding: 16px;
  background: rgba(4, 5, 8, 0.7);
  backdrop-filter: blur(8px);
  animation: overlay-in 0.25s ease;
}
@keyframes overlay-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
.load-panel,
.edit-panel {
  width: min(560px, 100%);
  max-height: 80vh;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--line-strong);
  border-radius: 18px;
  background: linear-gradient(160deg, rgba(24, 29, 42, 0.95), rgba(13, 16, 24, 0.98));
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.55);
  overflow: hidden;
  animation: panel-in 0.3s cubic-bezier(0.34, 1.4, 0.44, 1);
}
@keyframes panel-in {
  from {
    opacity: 0;
    transform: translateY(16px) scale(0.97);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.load-head,
.edit-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px;
  border-bottom: 1px solid var(--line);
}
.load-title,
.edit-title {
  font-family: var(--font-serif);
  font-size: 15px;
  letter-spacing: 0.08em;
  color: var(--bone);
}
.load-close {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 8px;
  color: var(--ash-dim);
  cursor: pointer;
  transition: all 0.2s ease;
}
.load-close :deep(svg) {
  width: 15px;
  height: 15px;
}
.load-close:hover {
  color: var(--bone);
  border-color: var(--line-bright);
  background: rgba(230, 226, 216, 0.06);
}
.load-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 14px 16px;
  overflow-y: auto;
}
.load-item {
  display: flex;
  gap: 12px;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: rgba(230, 226, 216, 0.02);
  color: var(--ash);
  text-align: left;
  cursor: pointer;
  transition: all 0.2s ease;
}
.load-item:hover {
  border-color: rgba(212, 168, 96, 0.45);
  background: rgba(212, 168, 96, 0.06);
  transform: translateX(2px);
}
.load-floor {
  flex: none;
  font-family: var(--font-display);
  font-size: 11px;
  color: var(--gold-soft);
  letter-spacing: 0.08em;
  padding-top: 2px;
}
.load-text {
  font-family: var(--font-serif);
  font-size: 12.5px;
  line-height: 1.6;
  color: var(--ash);
  display: -webkit-box;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* 长按上下文菜单 */
.context-menu {
  position: fixed;
  z-index: 100;
  min-width: 180px;
  padding: 6px;
  border: 1px solid var(--line-strong);
  border-radius: 14px;
  background: linear-gradient(160deg, rgba(24, 29, 42, 0.97), rgba(13, 16, 24, 0.98));
  box-shadow: 0 10px 34px rgba(0, 0, 0, 0.6), 0 0 0 1px rgba(212, 168, 96, 0.06);
  animation: menu-in 0.18s cubic-bezier(0.34, 1.4, 0.44, 1);
}
@keyframes menu-in {
  from {
    opacity: 0;
    transform: scale(0.94);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.ctx-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 4px 8px 8px;
  border-bottom: 1px solid var(--line);
}
.ctx-title {
  font-family: var(--font-serif);
  font-size: 11px;
  letter-spacing: 0.2em;
  color: var(--ash-dim);
}
.ctx-close {
  width: 22px;
  height: 22px;
  display: grid;
  place-items: center;
  color: var(--ash-faint);
  cursor: pointer;
  border-radius: 6px;
}
.ctx-close :deep(svg) {
  width: 13px;
  height: 13px;
}
.ctx-close:hover {
  color: var(--bone);
  background: rgba(230, 226, 216, 0.06);
}
.ctx-item {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 9px 10px;
  margin-top: 4px;
  border-radius: 9px;
  color: var(--ash);
  cursor: pointer;
  transition: all 0.18s ease;
}
.ctx-item:hover:not(:disabled) {
  color: var(--bone);
  background: rgba(212, 168, 96, 0.08);
}
.ctx-item:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}
.ctx-icon {
  width: 16px;
  height: 16px;
  display: grid;
  place-items: center;
  color: var(--gold);
}
.ctx-icon :deep(svg) {
  width: 15px;
  height: 15px;
}
.ctx-label {
  font-family: var(--font-serif);
  font-size: 13px;
  letter-spacing: 0.04em;
}

/* 编辑模态框 */
.edit-body {
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.edit-textarea {
  width: 100%;
  height: 320px;
  padding: 12px;
  resize: none;
  border: 1px solid var(--line-strong);
  border-radius: 12px;
  background: rgba(11, 14, 20, 0.7);
  color: var(--bone);
  font-family: var(--font-serif);
  font-size: 14px;
  line-height: 1.8;
  outline: none;
}
.edit-textarea:focus {
  border-color: rgba(212, 168, 96, 0.5);
  box-shadow: 0 0 0 3px rgba(212, 168, 96, 0.1);
}
.edit-actions {
  display: flex;
  gap: 10px;
  justify-content: flex-end;
}
.edit-btn {
  padding: 8px 20px;
  border: 1px solid var(--line-strong);
  border-radius: 10px;
  color: var(--ash);
  font-family: var(--font-serif);
  font-size: 13px;
  letter-spacing: 0.06em;
  cursor: pointer;
  transition: all 0.2s ease;
}
.edit-btn:hover {
  color: var(--bone);
  border-color: var(--line-bright);
  background: rgba(230, 226, 216, 0.05);
}
.edit-btn.primary {
  background: linear-gradient(135deg, var(--gold), #b98a43);
  color: #1a1208;
  border-color: transparent;
  box-shadow: 0 4px 16px rgba(212, 168, 96, 0.3);
}
.edit-btn.primary:hover {
  filter: brightness(1.06);
  color: #1a1208;
}
