
.detail-overlay {
  position: fixed;
  inset: 0;
  z-index: 60;
  display: grid;
  place-items: center;
  padding: 16px;
  background: rgba(4, 5, 8, 0.72);
  backdrop-filter: blur(8px);
  animation: overlay-in 0.25s ease;
}
@keyframes overlay-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
.detail-panel {
  width: min(560px, 100%);
  max-height: 84vh;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--line-strong);
  border-radius: 18px;
  background: linear-gradient(160deg, rgba(24, 29, 42, 0.95), rgba(13, 16, 24, 0.98));
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.55);
  overflow: hidden;
  animation: panel-in 0.3s cubic-bezier(0.34, 1.4, 0.44, 1);
}
@keyframes panel-in {
  from {
    opacity: 0;
    transform: translateY(16px) scale(0.97);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
.detail-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px;
  border-bottom: 1px solid var(--line);
}
.detail-title-wrap {
  display: flex;
  align-items: baseline;
  gap: 10px;
}
.detail-name {
  font-family: var(--font-serif);
  font-size: 20px;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: var(--bone);
}
.detail-meta {
  font-size: 12px;
  color: var(--ash-dim);
}
.detail-close {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 8px;
  color: var(--ash-dim);
  cursor: pointer;
  transition: all 0.2s ease;
}
.detail-close :deep(svg) {
  width: 15px;
  height: 15px;
}
.detail-close:hover {
  color: var(--bone);
  border-color: var(--line-bright);
  background: rgba(230, 226, 216, 0.06);
}
.detail-body {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 16px;
  overflow-y: auto;
}
.desc-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.desc-item {
  font-size: 13px;
  line-height: 1.7;
  color: var(--ash);
  padding: 9px 12px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: rgba(230, 226, 216, 0.02);
}
.desc-item i {
  font-style: normal;
  font-family: var(--font-serif);
  color: var(--ash-faint);
  letter-spacing: 0.12em;
  margin-right: 8px;
}
.yinxia-box {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px;
  border: 1px solid rgba(156, 120, 192, 0.25);
  border-radius: 12px;
  background: rgba(156, 120, 192, 0.06);
}
.yinxia-box .desc-item {
  border-color: rgba(156, 120, 192, 0.2);
}
